function focusLogique(){for(const id of ['boss','power','pause']){const b=$(id);if(b&&!b.disabled&&b.offsetParent!==null){b.focus();return}}}
function fermer(id){const el=$(id);if(el.hidden)return;const dedans=el.contains(document.activeElement);el.hidden=true;if(OUVREUR[id])$(OUVREUR[id]).setAttribute('aria-expanded','false');if(dedans)OUVREUR[id]?$(OUVREUR[id]).focus():focusLogique()}
