let recitCourant=null;
function majRecit(){if(recitCourant)return;const id=recitAAfficher(s,guide);if(!id||!$('guidepanel').hidden||!$('bossintro').hidden||!$('absenceintro').hidden||!$('succes').hidden)return;const r=RECITS.find(x=>x.id===id);recitCourant=id;$('recittitre').textContent=r.titre;$('recittexte').textContent=r.texte;$('recit').hidden=false;annonce(`${r.titre}. ${r.texte}`)}
